export function toposort(graph) {
  const order = [];
  const done = new Set();
  const onPath = [];

  function visit(node) {
    if (done.has(node)) return;
    const seenAt = onPath.indexOf(node);
    if (seenAt !== -1) {
      throw new Error(`cycle: ${[...onPath.slice(seenAt), node].join(' -> ')}`);
    }
    onPath.push(node);
    for (const dep of [...(graph[node] ?? [])].sort()) visit(dep);
    onPath.pop();
    done.add(node);
    order.push(node);
  }

  for (const node of Object.keys(graph).sort()) visit(node);
  return order;
}

